from robot.api import logger

from ta_egate_cmd_parser.egate_output_parser_base import EgateDispCommandsOutputParser
from ta_egate_cmd_parser.egate_command_base import EgateCommandBase
from ta_egate_cmd_parser.utils.converters import create_dict_with_key


class LaaCellParamFailure(Exception):
    """
    Exception class for laa_cell_param
    """
    pass


class LaaCellParam(EgateCommandBase):
    """
    Parser for laa_cell_param command output.
    """

    def __init__(self, **params):
        """

        :param params:
        """
        super(LaaCellParam, self).__init__()
        self.command = 'laa_cell_param'
        self.params = params
        self.fail_regexp = 'Error'
        self.to_execute = self.command
        self._build_command()
        logger.debug('{}: {} command to execute:\n{}'.format(self.__class__.__name__, self.command, self.to_execute))

    def _build_command(self):
        """
        Build laa_cell_param command.
        :return: None
        """
        for param, value in list(self.params.items()):
            if param == 'no_action' or param == 'clear_laa_counters' or param == 'reset_laa_cell_params':
                self.to_execute += ' {}'.format(param)
            else:
                self.to_execute += ' {}={}'.format(param, value)

    def execute(self, egate_id=0):
        """
        Execute laa_cell_param command.
        :return: command status and output
        """
        if "id" in list(self.params.keys()) and len(list(self.params.keys())) == 1:
            raise LaaCellParamFailure("Use execute_and_parse() method to parse output of {} cmd".format(self.command))
        else:
            self.executed_phrase = '.*?EGATE>'
            status, output = super(LaaCellParam, self).execute(egate_id=egate_id, command=self.to_execute, fail_regexp=self.fail_regexp)
            if status:
                return status, output
            else:
                raise LaaCellParamFailure(output)

    def execute_and_parse(self, egate_id=0):
        """
        Execute laa_cell_param command and parse its output.
        :return:
        """
        if "id" in list(self.params.keys()) and len(list(self.params.keys())) == 1:
            self.executed_phrase = r'.*?eNB-\d+\sCELL-\d+.*?EGATE>'
            status, output = super(LaaCellParam, self).execute(egate_id=egate_id, command=self.to_execute, fail_regexp=self.fail_regexp)
            if status:
                cmd_parser = EgateDispCommandsOutputParser(output)
                output = cmd_parser.get_list_of_output_parsed_lines()
                return create_dict_with_key(key='Parameter',
                                            list_of_output_parsed_lines=output)
        else:
            raise LaaCellParamFailure("Too many params! Use execute() method to execute {} cmd with: {}".format(self.command, self.params))
